import json
from collections import Counter
c=Counter()
for l in open('Observation.ndjson'):
    d=json.loads(l)
    for x in d.get('code',{}).get('coding',[]):
        dp=(x.get('display') or '')
        if any(k in dp.upper() for k in ['QT','ECG','EKG','RHYTHM','INR','FIBRIL']):
            c[(x.get('system'),x.get('code'),dp)]+=1
for k,v in c.most_common(): print(v,k)
"

